def greet(name):
    """Возвращает приветствие для указанного имени."""
    return f"Привет, {name}!"

import unittest

from greet import greet


class TestGreet(unittest.TestCase):
    def test_greet_name(self):
        self.assertEqual(greet("Мир"), "Привет, Мир!")

    def test_greet_latin_name(self):
        self.assertEqual(greet("Alice"), "Привет, Alice!")


if __name__ == "__main__":
    unittest.main()
